import{_ as t,o as l,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS G/H (Day 1) - CMake Update","description":"","frontmatter":{"title":"CDS G/H (Day 1) - CMake Update","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-24T00:00:00.000Z","tags":["[Ceph]","[CMake]","[CI/CD]","[Distributed Storage]","[CephFS]"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_CMake_Update.md","filePath":"posts/2014/CDS_G_H_Day_1_-_CMake_Update.md","lastUpdated":1780459816000}'),o={name:"posts/2014/CDS_G_H_Day_1_-_CMake_Update.md"};function s(n,e,r,C,_,p){return l(),i("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 项目中 CMake 更新及 CI 技术讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Matt Benjamin, Ilya Dryomov, Adam Emerson, Luis, Luke, Dan（可能还有其他未提及的人员）</p><p><strong>会议内容</strong>：</p><p><strong>一、CMake 更新</strong></p><ul><li><strong>项目背景</strong>： 为提升构建速度，特别是多核机器上的构建速度，项目组将构建系统从 Autoconf/Makefile 转换为 CMake。</li><li><strong>进展情况</strong>： <ul><li>实习生 Ali 完成了初步的转换工作，但后续人员在不同分支上进行了修改。</li><li>第一版 CMake 构建系统与 Autoconf/Makefile 基本一致，但缺少了测试等部分。</li><li>项目组通过减少重复构建的对象数量和简化文件结构，提高了构建速度。</li><li>目前，CMake 版本已合并到 Firefly 分支，并添加了测试。</li></ul></li><li><strong>下一步计划</strong>： <ul><li>将 CMake 版本合并到 master 分支。</li><li>检查是否存在遗漏的目标或其他问题。</li><li>确保所有边缘情况都能正常工作，例如库检测、构建脚本等。</li><li>移植 CMake 到 Civic Web 等其他子模块。</li></ul></li></ul><p><strong>二、CI 技术讨论</strong></p><ul><li><strong>议题</strong>： 讨论 CI 技术的选择和优先级。</li><li><strong>讨论内容</strong>： <ul><li>评估了 Jenkins、GitLab CI/CD 等不同的 CI 工具。</li><li>讨论了 CI 工具的集成、测试覆盖范围、性能等问题。</li><li>讨论了不同分支的测试策略。</li></ul></li><li><strong>结论</strong>： <ul><li>项目组对 CMake 的未来持乐观态度。</li><li>将 CMake 合并到 master 分支。</li><li>继续讨论 CI 技术的选择和实施计划。</li></ul></li></ul><p><strong>三、其他事项</strong></p><ul><li>Ilya Dryomov 正在研究构建目标在源树外部的情况。</li><li>项目组将继续关注 Civic Web 等其他子模块的 CMake 移植工作。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Matt Benjamin 将在当天晚些时候推送 CMake 的 master 分支原型。</li><li>项目组将检查 CMake 版本中是否存在遗漏的目标或其他问题。</li><li>项目组将讨论 CI 技术的选择和实施计划。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph 领域的英文关键词，例如：CMake, Autoconf, Makefile, Jenkins, GitLab CI/CD, Civic Web, RocksDB, BlueStore, RBD, CRC, Autoconf, Makefile, Jenkins, GitLab CI/CD 等。</li></ul>',15)])])}const k=t(o,[["render",s]]);export{g as __pageData,k as default};
